<div class="page-heading"><div><p class="eyebrow">Alunos</p><h1>Matrículas</h1><p class="meta">Acompanhe curso, cobrança e liberação acadêmica em um único fluxo.</p></div><a class="button-primary" href="<?= $escape($basePath) ?>/students/enrollments/create"><i class="fa-solid fa-plus"></i> Nova matrícula</a></div><?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?><section class="card"><div class="table-responsive"><table><thead><tr><th>Aluno</th><th>Curso</th><th>Unidade</th><th>Atendente</th><th>Financeiro</th><th>Acesso AVA</th><th>Ação</th></tr></thead><tbody><?php if($items===[]):?><tr><td colspan="7">Nenhuma matrícula cadastrada.</td></tr><?php endif;?><?php foreach($items as$item):$canDelete=$item['status']==='awaiting_charge'&&$item['finance_payment_id']===null&&$item['moodle_enrolment_status']==='not_released';?><tr><td><strong><?= $escape($item['student_name']) ?></strong><br><small><?= $escape($item['cpf_cnpj']?:'Sem documento') ?></small></td><td><?= $escape($item['course_name']) ?></td><td><?= $escape($item['unit_name']) ?></td><td><?= $escape($item['attendant_name']?:'Não definido') ?></td><td><span class="connection-badge"><?= $item['status']==='awaiting_charge'?'Aguardando cobrança':($item['status']==='awaiting_payment'?'Aguardando pagamento':$escape($item['status'])) ?></span><?php if($item['product_name']):?><br><small><?= $escape($item['product_name']) ?> · R$ <?= number_format((float)$item['value'],2,',','.') ?></small><?php endif;?></td><td><span class="connection-badge"><?= $item['moodle_enrolment_status']==='not_released'?'Não liberado':$escape($item['moodle_enrolment_status']) ?></span></td><td><div class="d-flex gap-2 flex-wrap"><?php if($item['status']==='awaiting_charge'):?><a class="button-primary button-small" href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$item['finance_customer_id'] ?>/payments/create?enrollment=<?= (int)$item['id'] ?>" title="Gerar cobrança"><i class="fa-solid fa-wallet"></i></a><?php endif;?><a class="button-secondary button-small" href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$item['finance_customer_id'] ?>" title="Abrir cadastro"><i class="fa-solid fa-eye"></i></a><?php if($canDelete):?><form class="inline-form" method="post" action="<?= $escape($basePath) ?>/students/enrollments/<?= (int)$item['id'] ?>/delete" data-confirm-submit="Excluir esta matrícula? Esta ação não poderá ser desfeita."><?= $csrfField ?><input type="hidden" name="confirm_delete" value="1"><button class="button-danger button-small" type="submit" title="Excluir matrícula" aria-label="Excluir matrícula"><i class="fa-solid fa-trash"></i></button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
